#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m08-label-surgery pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m08-label-surgery
CHECKS="quarantined-pod-unmatched quarantined-pod-stays replacement-created api-back-to-two"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m08-label-surgery
checks:
  - id: quarantined-pod-unmatched
    describe: No Pod named shelf-api-a has the label app.kubernetes.io/name=shelf-api any more
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-api
      - -o
      - json
    expect:
      jsonpath: '{.items[?(@.metadata.name=="shelf-api-a")].metadata.name}'
      equals: ""
    hint: "The ReplicaSet selects Pods with app.kubernetes.io/name=shelf-api. Change that label on shelf-api-a with `kubectl label pod shelf-api-a --namespace shelf app.kubernetes.io/name=... --overwrite`. Adding a second label does not help: the Pod would still match."
  - id: quarantined-pod-stays
    describe: The Pod shelf-api-a still exists and no ReplicaSet owns it
    kubectl:
      - get
      - pod
      - shelf-api-a
      - -n
      - shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 10s
        interval: 2s
        expect:
          jsonpath: "{.metadata.ownerReferences[*].name}"
          equals: ""
    hint: "Do not delete the Pod: the point is to keep it for debugging. Once its labels no longer match, the ReplicaSet removes itself from the Pod's ownerReferences, and `kubectl get pod shelf-api-a --namespace shelf --output yaml` shows no owner."
  - id: replacement-created
    describe: The ReplicaSet shelf-api owns a Pod that is not shelf-api-a or shelf-api-b, a replacement with a generated name
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          jsonpath: '{.items[?(@.metadata.ownerReferences[0].name=="shelf-api")].metadata.name}'
          matches: shelf-api-\w{5}\b
    hint: "The ReplicaSet counts the Pods that match its selector and want two. After the relabel it counts one, so it creates a new Pod: `kubectl get pods --namespace shelf` shows a third shelf-api Pod with a generated name."
  - id: api-back-to-two
    describe: The ReplicaSet shelf-api has 2 Ready replicas again
    kubectl:
      - get
      - replicaset
      - shelf-api
      - -n
      - shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          jsonpath: "{.status.readyReplicas}"
          equals: "2"
    hint: Give the replacement a few seconds to start. If it stays Pending or fails, `kubectl describe pod` on the new Pod shows why.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
